import { BarChart } from '@absoluteui/components/bar-chart';

const host = document.createElement('div');
document.body.append(host);
BarChart.create(host, {
  label: 'Support tickets by region',
  categories: ['North America', 'Europe', 'Asia Pacific'],
  series: [
    { id: 'open', label: 'Open', values: [34, 28, 19] },
    { id: 'closed', label: 'Closed', values: [120, 96, 88] },
  ],
  valueAxis: { label: 'Tickets' },
  valueLabels: true,
});

import { BarChart } from '@absoluteui/components/bar-chart';

const host = document.querySelector<HTMLElement>('#variance');
if (host) {
  const chart = BarChart.create(host, {
    label: 'Budget variance by department',
    categories: ['Engineering', 'Marketing', 'Finance'],
    series: [
      { id: 'capex', label: 'Capital', values: [40, 22, -8] },
      { id: 'opex', label: 'Operating', values: [25, -18, 12] },
    ],
    orientation: 'horizontal',
    layout: 'stacked',
    valueFormat: { style: 'currency', currency: 'EUR', notation: 'compact' },
  });
  chart.setSeriesVisible('opex', false);
}
